          "stem": "في الشكل المتعرج (Z) بين مستقيمين متوازيين، رُسمت قطعة منكسرة عند نقطة وسطى. إذا كانت الزاوية العليا ٤٠° والزاوية السفلى ٣٥°، فما قياس زاوية الانكسار س عند النقطة الوسطى؟",
