          "solution": "نمرّر مستقيماً مساعداً موازياً للمتوازيين عبر نقطة التقاء القاطعين.\nبالتبادل الداخلي تظهر ٦٠° فوق المساعد و٥٠° تحته على جهة واحدة، فالزاوية المحصورة بين القاطعين = ٦٠° + ٥٠° = ١١٠°.\nنقارن: ١١٠° > ٧٠°، فالقيمة الأولى أكبر.\nخطأ شائع: طرح المجموع من ١٨٠° فيظهر ٧٠°؛ الصحيح أن الزاويتين تتجمعان لا تتكاملان عند هذه النقطة.",
